/**
 * @method
 * @name scwin.checkForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param frm
 * @returns
 * @hidden N
*/
scwin.checkForm = async function (frm) {
    /* sdd-asis-lifecycle:begin checkForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    // 수동 전환 필요: MiyaValidator.validate → await $c.validate.validateDataCollect(grp, options)
    //   KRX 방향: 재설계다. 핸들러를 async 로 만들고, 산발적 검사(`if(!x){alert();obj.focus();return;}`)를 선언적 fields 명세 한 덩어리로 접는다 — `options = { validateType: "alert", checkType: "single", focus: true, fields: { ipb_comNm: { required: true, name: "법인명" }, … } }`. 알림·커서 이동은 라이브러리가 한다.
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    const v = new MiyaValidator(frm);
    if (scwin.leadcomCnt != 0) {
        v.add("listBrokerStkHdYn", { required: true });
        v.add("listBrokerEmpStkHdYn", { required: true });
    }
    const result = v.validate();
    if (!result) {
        const msg = v.getErrorMessage();
        await $c.win.alert(msg);
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkRate
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.checkRate = async function (obj) {
    /* sdd-asis-lifecycle:begin fn_checkRate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let result = obj.value;
    if (result === "") {
        result = "0";
    }
    result = Number(result.split(",").join(""));
    if (result > 100) {
        await $c.win.alert("100% 이하여야합니다.");
        obj.focus();
    }
    /* sdd-asis-lifecycle:end */
};


