};


/**
 * @method
 * @name scwin.makeNum
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.makeNum = function (val) {
    /* sdd-asis-lifecycle:begin makeNum — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let result = (document.preListForm || { elements: [] })[val].value;
    if (result === "") {
        result = "0";
    }
    result = result.split(",").join("");
    result = Number(result);
    return result;
    /* sdd-asis-lifecycle:end */
};
